pub fn rules_for_route(route_id: u16) -> impl Iterator<Item = &'static InterlockRule> {
    INTERLOCK_RULES
        .iter()
        .filter(move |rule| rule.route_id == route_id)
}

pub fn interlock_pressure(route_id: u16, seed: u32) -> u32 {
    let mut value = seed ^ route_id as u32;
    for rule in rules_for_route(route_id) {
        value = value.rotate_left((rule.rule_class & 31) as u32) ^ rule.pressure;
        value = value.wrapping_add(rule.timeout_ms as u32);
    }
    value % 1_000_000
}
